import licenses from './licenses.json';

/** Where the source code, the license texts and the privacy page are. */
export const SOURCE_URL = 'https://github.com/Yenis/portal-gems';

/** One bundled third-party component: its name, version and license. */
export type Component = readonly [name: string, version: string, license: string];

/**
 * What each app is built on, as listed on its About screen. Generated by
 * `scripts/gen-licenses.mjs` from the installed and locked dependencies -
 * run that after changing one; never edit `licenses.json` by hand.
 */
export const COMPONENTS = licenses as unknown as Record<
  'desktop' | 'android' | 'symbian',
  readonly Component[]
>;

/** A component as one line: `name 1.2.3 - MIT`. */
export function componentLine([name, version, license]: Component): string {
  return `${name}${version ? ` ${version}` : ''} - ${license}`;
}
